// Every mutable field uses COALESCE(narg, col) so a partial update cannot
// silently blank a column the caller did not mention. version is bumped by the
// statement itself, so the caller never has to read-modify-write it.
func (q *Queries) UpdateTestCase(ctx context.Context, arg UpdateTestCaseParams) (TestCase, error) {
	row := q.db.QueryRow(ctx, updateTestCase,
		arg.ID,
		arg.WorkspaceID,
		arg.Title,
		arg.Module,
		arg.Preconditions,
		arg.Steps,
		arg.ExpectedResult,
		arg.TestData,
		arg.Priority,
		arg.CaseType,
		arg.Scope,
		arg.ExecutionMode,
		arg.RequiredCapabilities,
		arg.BusinessRulesRef,
		arg.Status,
		arg.SourceRefs,
		arg.ReviewedBy,
		arg.ReviewedAt,
		arg.UpdatedBy,
	)
	var i TestCase
	err := row.Scan(
		&i.ID,
		&i.WorkspaceID,
		&i.ProjectID,
		&i.CaseNumber,
		&i.Title,
		&i.Module,
		&i.Preconditions,
		&i.Steps,
		&i.ExpectedResult,
		&i.TestData,
		&i.Priority,
		&i.CaseType,
		&i.Scope,
		&i.ExecutionMode,
		&i.RequiredCapabilities,
		&i.BusinessRulesRef,
		&i.Status,
		&i.Origin,
		&i.SourceRefs,
		&i.GenerationJobID,
		&i.Version,
		&i.CreatedBy,
		&i.UpdatedBy,
		&i.ReviewedBy,
		&i.ReviewedAt,
		&i.CreatedAt,
		&i.UpdatedAt,
	)
	return i, err
}
